// Select topic AND build OpenAI request body (no separate Build node = no json validation error)
const contentTypes = ["paper-summary","discovery","methodology","data-source","tool","case-study","trend","formula","documentation"];
const categories = ["nasa","orbital-mechanics","astrophysics","quantum-physics","aerospace","general"];
const topics = ["orbital debris mitigation","precision orbit determination","space weather effects","satellite constellation design","propulsion systems","attitude control","mission design","data analysis techniques","numerical methods","recent NASA discoveries","exoplanet research","black hole physics","quantum computing in space","materials science for space"];
const selectedType = contentTypes[Math.floor(Math.random() * contentTypes.length)];
const selectedCategory = categories[Math.floor(Math.random() * categories.length)];
const selectedTopic = topics[Math.floor(Math.random() * topics.length)];
const today = new Date().toISOString().split('T')[0];
const id = `research-${Date.now()}`;
const prompt = `Generate comprehensive research content for PhD students and researchers about ${selectedTopic} in the ${selectedCategory} category.

Content type: ${selectedType}

Requirements:
1. Provide a detailed summary (2-3 sentences)
2. Write full content suitable for research papers (500-1000 words)
3. Include relevant keywords
4. Provide references to academic papers, NASA documentation, or authoritative sources
5. Include formulas/equations if applicable
6. Include data points if applicable
7. Suggest related topics
8. Include SEO keywords

Format as JSON:
{
  "title": "...",
  "summary": "...",
  "content": "...",
  "keywords": ["..."],
  "references": [{"title": "...", "url": "...", "source": "...", "type": "paper|website|documentation|data|tool"}],
  "formulas": [{"name": "...", "equation": "...", "description": "..."}],
  "dataPoints": [{"label": "...", "value": "...", "unit": "...", "source": "..."}],
  "relatedTopics": ["..."],
  "seoKeywords": "..."
}`;
const openAIBody = JSON.stringify({ model: 'gpt-5-mini', messages: [{ role: 'user', content: prompt + '\n\nReturn ONLY valid JSON, no markdown, no explanations.' }], temperature: 0.7, max_tokens: 3000 });
return { json: { id, date: today, type: selectedType, category: selectedCategory, topic: selectedTopic, prompt, openAIBody } };

// Parse AI response and format for API - Robust version
// Handle when previous node returns json as string (e.g. HTTP response)
let inputData;
try {
  const raw = $input.item?.json ?? $input.first()?.json;
  inputData = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  inputData = $input;
}

if (!inputData || typeof inputData !== 'object') {
  throw new Error("No input data received from OpenAI node");
}

// Get AI response - try multiple possible structures
let aiResponse = "";
try {
  if (inputData.choices && inputData.choices[0] && inputData.choices[0].message) {
    aiResponse = inputData.choices[0].message.content;
  } else if (inputData.message && inputData.message.content) {
    aiResponse = inputData.message.content;
  } else if (inputData.content) {
    aiResponse = inputData.content;
  } else if (inputData.text) {
    aiResponse = inputData.text;
  } else if (typeof inputData === 'string') {
    aiResponse = inputData;
  } else {
    // Try to extract from nested structure
    aiResponse = JSON.stringify(inputData);
  }
} catch (e) {
  console.error("Error getting AI response:", e);
  aiResponse = "Error: Could not parse AI response";
}

if (!aiResponse || aiResponse.trim() === "") {
  throw new Error("Empty AI response received");
}

// Parse JSON response
let parsed = {};
try {
  // Remove markdown code blocks if present
  let cleanedResponse = aiResponse.trim();
  if (cleanedResponse.startsWith('```json')) {
    cleanedResponse = cleanedResponse.replace(/```json\s*/g, '').replace(/```\s*$/g, '');
  } else if (cleanedResponse.startsWith('```')) {
    cleanedResponse = cleanedResponse.replace(/```\s*/g, '').replace(/```\s*$/g, '');
  }
  parsed = JSON.parse(cleanedResponse);
} catch (e) {
  // If not JSON, create structure manually
  console.warn("Could not parse as JSON, creating fallback structure:", e.message);
  parsed = {
    title: "AI Generated Research Content",
    summary: aiResponse.substring(0, 200),
    content: aiResponse,
    keywords: [],
    references: [],
    relatedTopics: []
  };
}

// Get metadata from previous node
let metadata = {};
try {
  const selectTopicNode = $('Select Research Topic');
  metadata = selectTopicNode.item?.json || {};
} catch (e) {
  console.warn("Could not get metadata from Select Topic node:", e.message);
  metadata = {
    id: `research-${Date.now()}`,
    date: new Date().toISOString().split('T')[0],
    topic: "Research",
    type: "paper-summary",
    category: "nasa"
  };
}

// Ensure all required fields
const researchContent = {
  id: metadata.id || `research-${Date.now()}`,
  date: metadata.date || new Date().toISOString().split('T')[0],
  title: parsed.title || metadata.topic || "Research Content",
  type: metadata.type || "paper-summary",
  category: metadata.category || "nasa",
  summary: parsed.summary || parsed.content?.substring(0, 200) || aiResponse.substring(0, 200) || "Research content",
  content: parsed.content || aiResponse,
  keywords: parsed.keywords || [metadata.topic || "research", metadata.category || "nasa"],
  references: parsed.references || [
    {
      title: "NASA.gov",
      url: "https://www.nasa.gov/",
      source: "NASA",
      type: "website"
    }
  ],
  formulas: parsed.formulas || [],
  dataPoints: parsed.dataPoints || [],
  relatedTopics: parsed.relatedTopics || [],
  seoKeywords: parsed.seoKeywords || `${metadata.topic || "research"} ${metadata.category || "nasa"} research`
};

// Return in correct format - must be array
return [{ json: researchContent }];
